<#
  Fix-InstallAppAndPerf.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  PART 1 - LAUNCH DATE TO "SOON" (again)
  This zip predates the earlier Fix-LaunchDateToSoon.ps1 script, so
  "August 15" was still showing everywhere - including in Google's cached
  search snippet, which is why it showed an even older "Aug 10". That
  snippet is Google's own cache of a past crawl; it updates on its own
  once Google recrawls the live site (you can speed that up yourself via
  Google Search Console's "Request Indexing" if you want it sooner - not
  something fixable from the codebase). This script re-applies the same
  "launching soon" copy fix as before to:
    - src\components\ui\ShareButton.jsx
    - src\app\layout.js (title, meta description, Open Graph, Twitter card)
    - src\app\send-package\step-3\page.jsx (the order-blocking gate modal
      itself is untouched - only its date text changed)

  PART 2 - INSTALL APP FROM THE HOMEPAGE
  No budget for App Store/Play Store ranking right now, so this adds a
  direct install path instead, using the browser's own PWA install
  mechanism rather than an app store listing:
    - public\sw.js (new): a deliberately do-nothing service worker - it
      does NOT cache anything, every request just passes straight to the
      network. Some browsers require a registered service worker before
      they'll offer the install prompt at all; a caching one would risk
      serving stale prices/order status after a deploy (the exact bug
      ChunkErrorRecovery.jsx already had to fix once), so this one exists
      purely to satisfy that requirement without that risk.
    - src\components\ServiceWorkerRegister.jsx (new): registers it,
      mounted globally in layout.js.
    - src\components\InstallAppButton.jsx (new): shows a real one-tap
      "Install App" button on Chrome/Edge/Android (using the native
      beforeinstallprompt event) and hides itself once already installed.
      iOS Safari has no install-prompt API at all - that's an iOS platform
      restriction, not fixable from here - so on iOS this instead opens a
      short "Tap Share, then Add to Home Screen" instruction sheet.
    - src\app\page.js: added the button to the homepage nav.

  PART 3 - LIGHTER, FASTER LOAD
    - src\app\layout.js: removed the global `import
      'mapbox-gl/dist/mapbox-gl.css'` - every component that actually
      renders a map (MapCanvas, TrackingMap, MiniRouteMap, MapModal, the
      vendor dashboard) already imports this CSS itself, so the global
      import was pure duplication, forcing map styling onto every single
      page - homepage, terms, login, all of it - whether or not that page
      ever shows a map.
    - src\app\layout.js: ChatNotificationListener and
      OrderStatusNotificationListener now load via next/dynamic (ssr:
      false) instead of a static import, so their code ships as a
      separate chunk instead of bloating every page's main JS bundle -
      they only ever do anything for a logged-in vendor/rider anyway.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  every existing file it touches to .fix-backup-install-perf\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-InstallAppAndPerf.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-install-perf"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying install-app, launch-date, and performance fixes:" -ForegroundColor Cyan

$b64_LAYOUT = ""
Write-FileFromBase64 "src\app\layout.js" $b64_LAYOUT

$b64_HOMEPAGE = ""
Write-FileFromBase64 "src\app\page.js" $b64_HOMEPAGE

$b64_SHAREBUTTON = ""
Write-FileFromBase64 "src\components\ui\ShareButton.jsx" $b64_SHAREBUTTON

$b64_SENDSTEP3 = ""
Write-FileFromBase64 "src\app\send-package\step-3\page.jsx" $b64_SENDSTEP3

$b64_SWREGISTER = ""
Write-FileFromBase64 "src\components\ServiceWorkerRegister.jsx" $b64_SWREGISTER

$b64_INSTALLBUTTON = ""
Write-FileFromBase64 "src\components\InstallAppButton.jsx" $b64_INSTALLBUTTON

$b64_SWFILE = ""
Write-FileFromBase64 "public\sw.js" $b64_SWFILE

Write-Host "`nDone. Backups saved under .fix-backup-install-perf\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
